import React, { useState, useEffect, useCallback } from 'react'
import axios from 'axios'

interface typedb {
    data: {
        id: string;
        name: string;
        price: string;
    }[]
};


function convertData({ data }: typedb) {
    return data.reduce<any>((h, card) =>
        Object.assign(h, {
            [card.name]: (h[card.name] || [])
                .concat(
                    {
                        id: card.id,
                        price: card.price,
                    })
        }), {})
}


export function GetCards() {
    const [zxc, setZxc] = useState()
    axios.get("http://18.191.178.251:3000/getCards", {
        params: {
            value: 500
        }
    }).then((responce) => setZxc(convertData(responce)));


    return { zxc };
}


